const isDigit = (ch) => ch !== undefined && ch >= '0' && ch <= '9';

function tokenize(expr) {
  const tokens = [];
  let i = 0;
  while (i < expr.length) {
    const ch = expr[i];
    if (ch === ' ' || ch === '\t') {
      i += 1;
      continue;
    }
    if (isDigit(ch)) {
      let j = i;
      while (isDigit(expr[j])) j += 1;
      if (expr[j] === '.') {
        j += 1;
        if (!isDigit(expr[j])) throw new SyntaxError('a dot needs a digit after it');
        while (isDigit(expr[j])) j += 1;
      }
      tokens.push({ kind: 'number', value: Number(expr.slice(i, j)) });
      i = j;
      continue;
    }
    if (ch === '+' || ch === '-' || ch === '*' || ch === '/' || ch === '%'
      || ch === '(' || ch === ')') {
      tokens.push({ kind: ch });
      i += 1;
      continue;
    }
    throw new SyntaxError(`the character ${ch} is not part of the grammar`);
  }
  return tokens;
}

export function evaluate(expr) {
  if (typeof expr !== 'string') throw new TypeError('expr must be a string');
  const tokens = tokenize(expr);
  let pos = 0;
  const peek = () => tokens[pos];

  const parseExpression = () => {
    let left = parseTerm();
    for (;;) {
      const token = peek();
      if (token === undefined || (token.kind !== '+' && token.kind !== '-')) return left;
      pos += 1;
      const right = parseTerm();
      left = token.kind === '+' ? left + right : left - right;
    }
  };

  const parseTerm = () => {
    let left = parseUnary();
    for (;;) {
      const token = peek();
      if (token === undefined
        || (token.kind !== '*' && token.kind !== '/' && token.kind !== '%')) return left;
      pos += 1;
      const right = parseUnary();
      if (token.kind === '*') {
        left *= right;
        continue;
      }
      if (right === 0) throw new RangeError('division by zero');
      left = token.kind === '/' ? left / right : left % right;
    }
  };

  const parseUnary = () => {
    const token = peek();
    if (token === undefined) throw new SyntaxError('the expression ends too early');
    if (token.kind === '+') {
      pos += 1;
      return parseUnary();
    }
    if (token.kind === '-') {
      pos += 1;
      return -parseUnary();
    }
    return parsePrimary();
  };

  const parsePrimary = () => {
    const token = peek();
    if (token === undefined) throw new SyntaxError('the expression ends too early');
    if (token.kind === 'number') {
      pos += 1;
      return token.value;
    }
    if (token.kind === '(') {
      pos += 1;
      const value = parseExpression();
      const close = peek();
      if (close === undefined || close.kind !== ')') throw new SyntaxError('a ( was never closed');
      pos += 1;
      return value;
    }
    throw new SyntaxError('a value was expected');
  };

  const value = parseExpression();
  if (pos !== tokens.length) throw new SyntaxError('the expression has trailing input');
  return value;
}
